function renderBandProgress(d){const job=(d.jobs||[]).find(j=>['band_scan','band_survey'].includes(j.job_type)),host=el('bandProgressMap'),summary=el('bandProgressSummary');host.replaceChildren();if(!job){summary.textContent='Start a scan to see its position and ETA.';return}const pct=jobPercent(job),progress=document.createElement('progress');progress.className='bandProgress';progress.max=100;progress.value=pct;progress.setAttribute('aria-label',jobLabel(job)+' progress');host.append(progress);const c=job.config||{},s=job.summary||{},start=Number(c.start_frequency_hz||0)/1e6,stop=Number(c.stop_frequency_hz||0)/1e6,current=Number(s.current_frequency_hz||c.start_frequency_hz||0)/1e6;summary.textContent=`${start.toFixed(3)} MHz → ${stop.toFixed(3)} MHz · now ${current.toFixed(6)} MHz · ${Math.round(pct)}% · ${jobTiming(job,pct)}`}
