async function refreshDecoderCapabilities(){try{const c=await postOperation('/api/digital/capabilities',{}),fldigi=c.fldigi||{};el('decoderStatus').textContent=`Native decoders ready · WSJT-X ${c.wsjt_x?.available?'available':'not detected'} · Fldigi ${fldigi.available||fldigi.connected?'available':'not detected'}`}catch(e){el('decoderStatus').textContent='Capability check failed: '+e.message}}
async function refreshSstvCapabilities(){try{const c=await postOperation('/api/sstv/capabilities',{});el('sstvCapabilities').textContent=`Decoder ${c.available?'available':'not detected'} · ${(c.receiver_modes||['USB','NFM']).join(', ')} · ${(c.modes||[]).length||'multiple'} VIS modes`}catch(e){el('sstvCapabilities').textContent='Capability check failed: '+e.message}}
el('profileForm').addEventListener('submit',async event=>{event.preventDefault();const ids=[...el('profileMemories').selectedOptions].map(o=>o.value),status=el('profileStatus');if(!ids.length){status.textContent='Select at least one station memory.';return}try{const duration=Number(el('profileDuration').value);await postOperation('/api/station-scan-profiles',{name:el('profileName').value,memory_ids_or_names:ids,duration_seconds:duration,max_memories:ids.length,compare_previous:true});status.textContent='Profile created. Use Run scan now below to collect the first observations.';event.target.reset();await refreshOperations()}catch(e){status.textContent='Profile failed: '+e.message}});
el('scheduleForm').addEventListener('submit',async event=>{event.preventDefault();const status=el('scheduleStatus');try{await postOperation('/api/station-schedules',{name:el('scheduleName').value,preset_id_or_name:el('scheduleProfile').value,interval_seconds:Math.round(Number(el('scheduleMinutes').value)*60),enabled:el('scheduleEnabled').value==='true'});status.textContent='Schedule saved.';event.target.reset();await refreshOperations()}catch(e){status.textContent='Schedule failed: '+e.message}});
async function refresh(){try{const response=await fetch('/api/dashboard',{cache:'no-store'});if(!response.ok)throw new Error('Status '+response.status);const d=await response.json();el('service').textContent=d.active_long_job?'Busy':'Online';el('service').className=d.active_long_job?'':'on';el('receivers').textContent=d.coordinator.receiver_count;el('leases').textContent=d.coordinator.active_lease_count;el('jobcount').textContent=d.jobs.length;rows('receiverRows',d.coordinator.receivers,r=>[txt('td',r.name),txt('td',r.backend),txt('td',r.role),txt('td',r.lease?'Leased':r.enabled?(r.verified?'Ready':'Unverified'):'Disabled')]);rows('jobRows',d.jobs,j=>[txt('td',j.job_type),txt('td',j.state),txt('td',(j.created_at||'').replace('T',' ').slice(0,19))]);rows('artifactRows',d.artifacts,a=>{const link=txt('a',a.filename);link.href=a.download_path;const td=document.createElement('td');td.append(link);return[td,txt('td',a.kind),txt('td',fmt(a.size_bytes))]});const s=d.storage;el('storage').textContent=JSON.stringify(s,null,2);el('storage').style.whiteSpace='pre-wrap';el('error').style.display='none'}catch(e){el('error').textContent='Dashboard refresh failed: '+e.message;el('error').style.display='block'}}
el('captureForm').addEventListener('submit',async event=>{event.preventDefault();const button=el('captureButton'),status=el('captureStatus');button.disabled=true;status.textContent='Capturing and analyzing…';try{const response=await fetch('/api/spectrum',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({center_frequency_hz:frequencyValue('frequency'),duration_seconds:Number(el('duration').value),fft_size:Number(el('fft').value),threshold_above_noise_db:Number(el('threshold').value),max_peaks:20})});const d=await response.json();if(d.coordinator)dashboardReceivers=d.coordinator.receivers||[];if(!response.ok)throw new Error(d.detail||d.error);status.textContent=`Completed ${(d.center_frequency_hz/1e6).toFixed(6)} MHz · ${d.peak_count} peaks · noise floor ${Number(d.relative_noise_floor_db).toFixed(1)} dB (relative)`;if(d.plot_artifact){const image=el('spectrumPlot');image.src=d.plot_artifact.download_path+'?t='+Date.now();image.style.display='block';makeZoomableImage(image,{title:`Spectrum plot at ${(d.center_frequency_hz/1e6).toFixed(6)} MHz`,downloadUrl:d.plot_artifact.download_path})}await refresh()}catch(e){status.textContent='Capture failed: '+e.message}finally{button.disabled=false}});refresh();setInterval(refresh,15000);
const modeDefaults={am:10000,nfm:12500,usb:3000,lsb:3000,cw:500};el('audioMode').addEventListener('change',()=>el('audioBandwidth').value=modeDefaults[el('audioMode').value]);el('audioForm').addEventListener('submit',async event=>{event.preventDefault();const button=el('audioButton'),status=el('audioStatus');button.disabled=true;status.textContent='Capturing and demodulating…';try{const response=await fetch('/api/demodulate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({frequency_hz:frequencyValue('audioFrequency'),mode:el('audioMode').value,bandwidth_hz:Number(el('audioBandwidth').value),duration_seconds:Number(el('audioDuration').value),fft_size:16384,cw_tone_hz:700})});const d=await response.json();if(d.coordinator)dashboardReceivers=d.coordinator.receivers||[];if(!response.ok)throw new Error(d.detail||d.error);const snr=d.metrics.estimated_snr_db;status.textContent=`${d.mode.toUpperCase()} · ${d.bandwidth_hz} Hz · estimated SNR ${Number(snr).toFixed(1)} dB (relative)`;if(d.audio_artifact){const player=el('audioPlayer');player.src=d.audio_artifact.download_path+'?t='+Date.now();player.style.display='block';player.load();try{await player.play()}catch(e){status.textContent+=' · Press Play to hear the recording.'}}for(const [id,item] of [['rfAnalysisPlot',d.rf_plot_artifact],['audioAnalysisPlot',d.audio_plot_artifact]])if(item){const image=el(id);image.src=item.download_path+'?t='+Date.now();image.style.display='block';makeZoomableImage(image,{title:`${d.mode.toUpperCase()} ${id==='rfAnalysisPlot'?'RF':'audio'} analysis at ${(d.frequency_hz/1e6).toFixed(6)} MHz`,downloadUrl:item.download_path})}await refresh()}catch(e){status.textContent='Demodulation failed: '+e.message}finally{button.disabled=false}});
el('fmForm').addEventListener('submit',async event=>{event.preventDefault();const button=el('fmButton'),status=el('fmStatus');button.disabled=true;status.textContent=`Receiving ${formatFrequency(frequencyValue('fmFrequency'))} wideband FM and decoding RDS…`;try{const response=await fetch('/api/broadcast-fm',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({frequency_hz:frequencyValue('fmFrequency'),duration_seconds:Number(el('fmDuration').value),stereo:el('fmStereo').value==='true',deemphasis_us:Number(el('fmDeemphasis').value),decode_rds_data:true})});const d=await response.json();if(d.coordinator)dashboardReceivers=d.coordinator.receivers||[];if(!response.ok)throw new Error(d.detail||d.error);const m=d.metrics||{};status.textContent=`${(d.frequency_hz/1e6).toFixed(1)} MHz · ${m.audio_channels||1} channel(s) · stereo pilot ${m.stereo_detected?'detected':'not detected'}`;const station=(d.rds||{}).station||{},groups=(d.rds||{}).group_count||0;el('rdsStatus').textContent=groups?`RDS: ${station.program_service||'Unknown station'} · ${station.radiotext||''} · ${groups} valid group(s)`:'No checksum-valid RDS groups decoded in this capture.';if(d.audio_artifact){const player=el('fmPlayer');player.src=d.audio_artifact.download_path+'?t='+Date.now();player.style.display='block';player.load();try{await player.play()}catch(e){status.textContent+=' · Press Play to hear the recording.'}}if(d.multiplex_plot_artifact){const image=el('fmPlot');image.src=d.multiplex_plot_artifact.download_path+'?t='+Date.now();image.style.display='block';makeZoomableImage(image,{title:`FM multiplex plot at ${(d.frequency_hz/1e6).toFixed(1)} MHz`,downloadUrl:d.multiplex_plot_artifact.download_path})}await refresh()}catch(e){status.textContent='Broadcast FM failed: '+e.message}finally{button.disabled=false}});refresh();refreshMemories();refreshOperations();refreshDecoderCapabilities();refreshSstvCapabilities();el('spotFilter').addEventListener('input',refreshOperations);setInterval(refresh,15000);setInterval(refreshMemories,15000);setInterval(refreshOperations,15000);setInterval(()=>{if(el('receiverBar').classList.contains('busy'))refreshOperations()},3000);
